insert into public.courses (goal, slug, title, description, ai_persona, cover_image, sort_order) values ('presentation', 'presentation', '{"vi":"Khóa luyện thuyết trình","en":"Presentation course"}'::jsonb, '{"vi":"Thuyết trình trên lớp, hội thảo, bảo vệ đồ án.","en":"Class presentations, seminars, thesis defence."}'::jsonb, '{"name":"Cô Hạnh","role":{"vi":"Giảng viên phản biện","en":"Critical lecturer"},"focus":{"vi":"cấu trúc, logic và cách dẫn dắt","en":"structure, logic and flow"},"questions":[{"vi":"Em có thể đưa một ví dụ thực tế cho luận điểm thứ hai không?","en":"Can you give a real example for your second point?"},{"vi":"Nguồn số liệu em dùng là từ năm nào?","en":"Which year is your data from?"},{"vi":"Nếu chỉ có 30 giây, em sẽ giữ lại ý nào?","en":"If you only had 30 seconds, which point would you keep?"}]}'::jsonb, 'stage.jpg', 0) on conflict (goal) do update set title = excluded.title, description = excluded.description, ai_persona = excluded.ai_persona, cover_image = excluded.cover_image, sort_order = excluded.sort_order;
