insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pr1', 1, 'structure', '{"vi":"Cấu trúc 3 phần: mở, thân, kết","en":"The three-part structure"}'::jsonb, '[{"vi":"Mở bài nêu vấn đề và lý do người nghe nên quan tâm.","en":"The opening states the problem and why the audience should care."},{"vi":"Thân bài có tối đa 3 ý chính, mỗi ý kèm một ví dụ.","en":"The body has at most 3 key points, each with an example."},{"vi":"Kết bài nhắc lại thông điệp và một việc người nghe nên làm.","en":"The closing repeats the message and one thing the audience should do."}]'::jsonb, '{"vi":"Viết một câu tóm tắt cả bài trước khi viết chi tiết.","en":"Write one sentence that sums up the whole talk before writing the details."}'::jsonb, '{"vi":"Viết kịch bản 1 phút giới thiệu môn học bạn thích nhất, đủ 3 phần.","en":"Write a 1-minute script introducing your favourite subject, with all 3 parts."}'::jsonb, 'script', 60, 10 from public.courses where goal = 'presentation' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pr2', 2, 'opening', '{"vi":"Mở bài 30 giây gây chú ý","en":"A 30-second opening that hooks"}'::jsonb, '[{"vi":"Ba cách mở hiệu quả: một câu hỏi, một con số, một câu chuyện ngắn.","en":"Three openings that work: a question, a number, a short story."},{"vi":"Tránh mở bằng “Hôm nay em xin trình bày về…”.","en":"Avoid opening with “Today I’m going to talk about…”."},{"vi":"Nói câu mở chậm hơn bình thường và nhìn thẳng khán giả.","en":"Say your first line slower than usual and look at the audience."}]'::jsonb, '{"vi":"Học thuộc 2 câu đầu tiên. Phần còn lại có thể linh hoạt.","en":"Memorise your first two sentences. The rest can be flexible."}'::jsonb, '{"vi":"Ghi âm 3 câu mở khác nhau cho chủ đề “Ứng dụng AI trong giáo dục”.","en":"Record 3 different openings for “AI in education”."}'::jsonb, 'audio', 45, 12 from public.courses where goal = 'presentation' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pr3', 3, 'pace', '{"vi":"Nhịp nói và ngắt nghỉ","en":"Pace and pauses"}'::jsonb, '[{"vi":"Tốc độ dễ nghe là 120–150 từ mỗi phút.","en":"An easy-to-follow pace is 120–150 words per minute."},{"vi":"Dừng 1 giây sau mỗi ý chính để người nghe kịp ghi nhớ.","en":"Pause for one second after each key point."},{"vi":"Chậm lại khi đọc số liệu hoặc tên riêng.","en":"Slow down for numbers and names."}]'::jsonb, '{"vi":"Đánh dấu “/” vào kịch bản ở những chỗ cần dừng.","en":"Mark “/” in your script wherever you want to pause."}'::jsonb, '{"vi":"Trình bày 2 phút về một số liệu khiến bạn bất ngờ, dừng sau mỗi ý.","en":"Talk for 2 minutes about a statistic that surprised you, pausing after each point."}'::jsonb, 'audio', 120, 12 from public.courses where goal = 'presentation' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pr4', 4, 'body', '{"vi":"Ánh mắt và cử chỉ","en":"Eye contact and gestures"}'::jsonb, '[{"vi":"Chia khán giả thành 3 vùng và lần lượt nhìn từng vùng.","en":"Split the audience into 3 zones and look at each in turn."},{"vi":"Dùng tay đếm ý khi liệt kê.","en":"Use your fingers to count points when listing."},{"vi":"Đứng vững, hai chân rộng bằng vai, không đung đưa.","en":"Stand steady, feet shoulder-width apart, no swaying."}]'::jsonb, '{"vi":"Quay video và xem lại không có tiếng để thấy rõ cử chỉ.","en":"Record yourself and watch it on mute to see your gestures clearly."}'::jsonb, '{"vi":"Quay video 90 giây trình bày 3 lợi ích của việc đọc sách.","en":"Record a 90-second video on 3 benefits of reading."}'::jsonb, 'video', 90, 15 from public.courses where goal = 'presentation' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.courses (goal, slug, title, description, ai_persona, cover_image, sort_order) values ('reporting', 'reporting', '{"vi":"Khóa luyện báo cáo","en":"Reporting course"}'::jsonb, '{"vi":"Báo cáo tiến độ, kết quả dự án, họp định kỳ.","en":"Progress updates, project results, team meetings."}'::jsonb, '{"name":"Chị Thảo","role":{"vi":"Trưởng phòng vận hành","en":"Operations manager"},"focus":{"vi":"rõ ràng, súc tích, số liệu chính xác","en":"clarity, brevity, accurate numbers"},"questions":[{"vi":"Chỉ số nào chưa đạt mục tiêu, nguyên nhân là gì?","en":"Which metric missed its target, and why?"},{"vi":"Rủi ro lớn nhất cho tháng tới là gì?","en":"What is the biggest risk for next month?"},{"vi":"Bạn cần hỗ trợ gì từ các phòng ban khác?","en":"What support do you need from other teams?"}]}'::jsonb, 'report.jpg', 1) on conflict (goal) do update set title = excluded.title, description = excluded.description, ai_persona = excluded.ai_persona, cover_image = excluded.cover_image, sort_order = excluded.sort_order;
