insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 're1', 1, 'structure', '{"vi":"Khung Kết quả, Vấn đề, Đề xuất","en":"Results, Issues, Proposal"}'::jsonb, '[{"vi":"Bắt đầu bằng kết quả chính trong một câu.","en":"Start with the main result in one sentence."},{"vi":"Nêu vấn đề kèm nguyên nhân, không đổ lỗi.","en":"State issues with causes, without blaming."},{"vi":"Kết bằng đề xuất cụ thể và việc cần người nghe quyết định.","en":"End with a concrete proposal and what you need decided."}]'::jsonb, '{"vi":"Người nghe bận rộn: điều quan trọng nhất nói trước.","en":"Busy listeners: say the most important thing first."}'::jsonb, '{"vi":"Viết kịch bản báo cáo tiến độ 90 giây theo khung 3 phần.","en":"Write a 90-second progress report script using the 3-part frame."}'::jsonb, 'script', 90, 10 from public.courses where goal = 'reporting' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 're2', 2, 'content', '{"vi":"Trình bày số liệu dễ hiểu","en":"Presenting numbers clearly"}'::jsonb, '[{"vi":"Mỗi câu chỉ nên có một con số.","en":"Use only one number per sentence."},{"vi":"Làm tròn số và so sánh với mục tiêu hoặc kỳ trước.","en":"Round numbers and compare them with the target or last period."},{"vi":"Nói ý nghĩa của con số, không chỉ đọc con số.","en":"Explain what the number means, not just the number."}]'::jsonb, '{"vi":"“Đạt 70% kế hoạch” dễ nhớ hơn “7 trên 10 hạng mục”.","en":"“70% of plan” is easier to remember than “7 of 10 items”."}'::jsonb, '{"vi":"Báo cáo kết quả kinh doanh tháng trước với 3 con số chính.","en":"Report last month’s sales results with 3 key numbers."}'::jsonb, 'audio', 90, 12 from public.courses where goal = 'reporting' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 're3', 3, 'filler', '{"vi":"Bỏ từ đệm khi báo cáo","en":"Cutting filler words"}'::jsonb, '[{"vi":"Từ đệm như “ừm”, “à”, “kiểu như” làm bạn kém chắc chắn.","en":"Fillers like “um”, “uh”, “like” make you sound unsure."},{"vi":"Khi cần suy nghĩ, hãy im lặng một nhịp.","en":"When you need to think, pause silently."},{"vi":"Chuẩn bị sẵn câu chuyển ý để không bị khựng.","en":"Prepare transition phrases so you never stall."}]'::jsonb, '{"vi":"Tập nói chậm hơn 10%: từ đệm giảm rõ rệt.","en":"Speak 10% slower and your fillers drop noticeably."}'::jsonb, '{"vi":"Báo cáo 1 phút về một hạng mục bị chậm, không dùng từ đệm.","en":"Give a 1-minute update on a late task with no filler words."}'::jsonb, 'audio', 60, 10 from public.courses where goal = 'reporting' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 're4', 4, 'qa', '{"vi":"Trả lời câu hỏi của cấp trên","en":"Answering your manager’s questions"}'::jsonb, '[{"vi":"Trả lời thẳng câu hỏi trong câu đầu tiên.","en":"Answer the question directly in your first sentence."},{"vi":"Thêm một lý do hoặc số liệu để chứng minh.","en":"Add one reason or number as evidence."},{"vi":"Nếu chưa biết, hẹn thời điểm trả lời cụ thể.","en":"If you don’t know, promise a specific time to follow up."}]'::jsonb, '{"vi":"Lặp lại ngắn câu hỏi giúp bạn có thêm 2 giây suy nghĩ.","en":"Briefly repeating the question buys you 2 seconds to think."}'::jsonb, '{"vi":"Trả lời: “Rủi ro lớn nhất cho tháng tới là gì?”","en":"Answer: “What is the biggest risk for next month?”"}'::jsonb, 'audio', 60, 12 from public.courses where goal = 'reporting' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.courses (goal, slug, title, description, ai_persona, cover_image, sort_order) values ('interview', 'interview', '{"vi":"Khóa luyện phỏng vấn","en":"Interview course"}'::jsonb, '{"vi":"Phỏng vấn xin việc, học bổng, câu lạc bộ.","en":"Job, scholarship and club interviews."}'::jsonb, '{"name":"Anh Khoa","role":{"vi":"Chuyên viên tuyển dụng","en":"Recruiter"},"focus":{"vi":"sự tự tin, ví dụ cụ thể và độ phù hợp","en":"confidence, concrete examples and fit"},"questions":[{"vi":"Kết quả cụ thể của dự án đó là gì?","en":"What was the concrete result of that project?"},{"vi":"Bạn sẽ làm gì trong 30 ngày đầu tiên?","en":"What would you do in your first 30 days?"},{"vi":"Mức lương mong muốn của bạn là bao nhiêu?","en":"What salary are you expecting?"}]}'::jsonb, 'interview.jpg', 2) on conflict (goal) do update set title = excluded.title, description = excluded.description, ai_persona = excluded.ai_persona, cover_image = excluded.cover_image, sort_order = excluded.sort_order;
