insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'in1', 1, 'opening', '{"vi":"Giới thiệu bản thân 60 giây","en":"Your 60-second introduction"}'::jsonb, '[{"vi":"Hiện tại: bạn là ai, đang làm gì.","en":"Present: who you are and what you do now."},{"vi":"Quá khứ: một thành tích liên quan tới vị trí.","en":"Past: one achievement relevant to the role."},{"vi":"Tương lai: vì sao bạn muốn vị trí này.","en":"Future: why you want this role."}]'::jsonb, '{"vi":"Kết thúc bằng lý do bạn phù hợp, không phải “em hết rồi ạ”.","en":"End with why you fit, not “that’s all”."}'::jsonb, '{"vi":"Ghi âm phần giới thiệu bản thân trong 60 giây.","en":"Record your self-introduction in 60 seconds."}'::jsonb, 'audio', 60, 10 from public.courses where goal = 'interview' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'in2', 2, 'structure', '{"vi":"Trả lời theo khung STAR","en":"Answering with STAR"}'::jsonb, '[{"vi":"Tình huống và nhiệm vụ: bối cảnh ngắn gọn.","en":"Situation and task: brief context."},{"vi":"Hành động: bạn đã làm gì, dùng “em” thay vì “nhóm”.","en":"Action: what you did, say “I”, not “we”."},{"vi":"Kết quả: con số hoặc thay đổi cụ thể.","en":"Result: a number or a concrete change."}]'::jsonb, '{"vi":"Dành 60% thời lượng cho phần Hành động.","en":"Spend 60% of your answer on the Action."}'::jsonb, '{"vi":"Viết câu trả lời STAR cho: “Kể về một lần bạn giải quyết mâu thuẫn trong nhóm.”","en":"Write a STAR answer to: “Tell me about a time you resolved a team conflict.”"}'::jsonb, 'script', 90, 15 from public.courses where goal = 'interview' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'in3', 3, 'filler', '{"vi":"Tự tin, không ậm ừ","en":"Confident, no hesitation"}'::jsonb, '[{"vi":"Câu hỏi khó: hít một hơi trước khi trả lời.","en":"Hard question: take a breath before answering."},{"vi":"Dùng câu đệm có nghĩa: “Đó là câu hỏi hay, em nghĩ…”.","en":"Use meaningful bridges: “Good question, I think…”."},{"vi":"Nói rõ, kết câu dứt khoát, không lên giọng cuối câu.","en":"Finish sentences firmly, without rising intonation."}]'::jsonb, '{"vi":"Ghi âm và đếm số lần “ừm”: mục tiêu dưới 2 lần mỗi phút.","en":"Record and count your “ums”: aim for under 2 per minute."}'::jsonb, '{"vi":"Trả lời “Điểm yếu lớn nhất của bạn là gì?” trong 1 phút.","en":"Answer “What is your biggest weakness?” in 1 minute."}'::jsonb, 'audio', 60, 10 from public.courses where goal = 'interview' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'in4', 4, 'closing', '{"vi":"Đặt câu hỏi ngược cho nhà tuyển dụng","en":"Asking the recruiter good questions"}'::jsonb, '[{"vi":"Hỏi về công việc thật: 3 tháng đầu cần đạt gì.","en":"Ask about the real job: what success looks like in 3 months."},{"vi":"Hỏi về đội nhóm và cách làm việc.","en":"Ask about the team and how it works."},{"vi":"Tránh hỏi lương ở vòng đầu, trừ khi được hỏi.","en":"Avoid asking about salary in the first round unless asked."}]'::jsonb, '{"vi":"Chuẩn bị sẵn 3 câu, dùng 1–2 câu tùy thời gian.","en":"Prepare 3 questions and use 1–2 depending on time."}'::jsonb, '{"vi":"Ghi âm phần kết buổi phỏng vấn kèm 2 câu hỏi cho nhà tuyển dụng.","en":"Record your interview closing with 2 questions for the recruiter."}'::jsonb, 'audio', 45, 10 from public.courses where goal = 'interview' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.courses (goal, slug, title, description, ai_persona, cover_image, sort_order) values ('pitching', 'pitching', '{"vi":"Khóa luyện gọi vốn","en":"Pitching course"}'::jsonb, '{"vi":"Giới thiệu sản phẩm, thuyết phục nhà đầu tư trong 3–5 phút.","en":"Pitch a product and convince investors in 3–5 minutes."}'::jsonb, '{"name":"Anh Minh","role":{"vi":"Nhà đầu tư thiên thần","en":"Angel investor"},"focus":{"vi":"sức thuyết phục, con số và lời kêu gọi","en":"persuasion, numbers and the ask"},"questions":[{"vi":"Mô hình doanh thu là gì, và bao lâu thì hòa vốn?","en":"What is your revenue model, and when do you break even?"},{"vi":"Đối thủ lớn nhất là ai? Vì sao khách hàng chọn bạn?","en":"Who is your main competitor? Why would customers choose you?"},{"vi":"Bạn cần bao nhiêu vốn và sẽ dùng vào việc gì?","en":"How much are you raising, and what will you use it for?"}]}'::jsonb, 'pitch.jpg', 3) on conflict (goal) do update set title = excluded.title, description = excluded.description, ai_persona = excluded.ai_persona, cover_image = excluded.cover_image, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('pitching', 'pitching-1', '{"vi":"Gọi vốn cho ứng dụng đặt sân thể thao dành cho sinh viên","en":"Pitch a sports court booking app for students"}'::jsonb, 0) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('pitching', 'pitching-2', '{"vi":"Thuyết phục nhà đầu tư trong 60 giây (elevator pitch)","en":"Convince an investor in 60 seconds (elevator pitch)"}'::jsonb, 1) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('pitching', 'pitching-3', '{"vi":"Giới thiệu sản phẩm mới cho khách hàng doanh nghiệp","en":"Introduce a new product to business customers"}'::jsonb, 2) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('pitching', 'pitching-4', '{"vi":"Trình bày kế hoạch mở rộng thị trường","en":"Present a market expansion plan"}'::jsonb, 3) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pi1', 1, 'opening', '{"vi":"Nêu vấn đề trong 20 giây","en":"State the problem in 20 seconds"}'::jsonb, '[{"vi":"Nhà đầu tư cần thấy vấn đề có thật và đủ lớn.","en":"Investors need to see a real, big enough problem."},{"vi":"Dùng một con số hoặc một khách hàng cụ thể.","en":"Use a number or a specific customer."},{"vi":"Không giới thiệu sản phẩm trước khi nêu vấn đề.","en":"Don’t introduce the product before the problem."}]'::jsonb, '{"vi":"“Mỗi tuần, sinh viên mất 40 phút để tìm sân” mạnh hơn “tìm sân rất khó”.","en":"“Students lose 40 minutes a week finding a court” beats “finding a court is hard”."}'::jsonb, '{"vi":"Ghi âm 20 giây nêu vấn đề mà sản phẩm của bạn giải quyết.","en":"Record 20 seconds stating the problem your product solves."}'::jsonb, 'audio', 30, 10 from public.courses where goal = 'pitching' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pi2', 2, 'content', '{"vi":"Giải pháp và con số chứng minh","en":"Solution and proof"}'::jsonb, '[{"vi":"Giải pháp nói trong một câu: cho ai, làm gì, khác biệt gì.","en":"Describe the solution in one sentence: for whom, what, what’s different."},{"vi":"Bằng chứng: người dùng, doanh thu, tỉ lệ quay lại.","en":"Proof: users, revenue, retention."},{"vi":"Mô hình kinh doanh: thu tiền từ đâu, bao nhiêu.","en":"Business model: who pays and how much."}]'::jsonb, '{"vi":"Ba con số tốt hơn mười con số.","en":"Three numbers beat ten."}'::jsonb, '{"vi":"Viết kịch bản 2 phút gồm vấn đề, giải pháp và 3 con số chứng minh.","en":"Write a 2-minute script with the problem, solution and 3 proof numbers."}'::jsonb, 'script', 120, 15 from public.courses where goal = 'pitching' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pi3', 3, 'closing', '{"vi":"Lời kêu gọi đầu tư rõ ràng","en":"A clear investment ask"}'::jsonb, '[{"vi":"Nêu số vốn cần gọi.","en":"State how much you are raising."},{"vi":"Nêu vốn dùng vào việc gì và mốc thời gian.","en":"Say what it is for and the timeline."},{"vi":"Kết bằng một câu mời hành động.","en":"End with a call to action."}]'::jsonb, '{"vi":"Đừng kết bằng “vậy thôi ạ”. Kết bằng con số.","en":"Don’t end with “that’s it”. End with a number."}'::jsonb, '{"vi":"Ghi âm 30 giây lời kêu gọi đầu tư.","en":"Record a 30-second investment ask."}'::jsonb, 'audio', 30, 10 from public.courses where goal = 'pitching' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'pi4', 4, 'qa', '{"vi":"Trả lời câu hỏi khó của nhà đầu tư","en":"Handling tough investor questions"}'::jsonb, '[{"vi":"Câu hỏi về đối thủ: thừa nhận, rồi nêu khác biệt.","en":"Competitor questions: acknowledge, then differentiate."},{"vi":"Câu hỏi về rủi ro: nêu kế hoạch giảm rủi ro.","en":"Risk questions: give your mitigation plan."},{"vi":"Không tranh cãi, không né câu hỏi.","en":"Don’t argue and don’t dodge."}]'::jsonb, '{"vi":"Trả lời trong 30–45 giây, rồi dừng.","en":"Answer in 30–45 seconds, then stop."}'::jsonb, '{"vi":"Trả lời: “Đối thủ lớn nhất là ai? Vì sao khách hàng chọn bạn?”","en":"Answer: “Who is your main competitor? Why would customers choose you?”"}'::jsonb, 'audio', 60, 15 from public.courses where goal = 'pitching' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.courses (goal, slug, title, description, ai_persona, cover_image, sort_order) values ('debating', 'debating', '{"vi":"Khóa luyện tranh biện","en":"Debating course"}'::jsonb, '{"vi":"Lập luận, phản biện, bảo vệ quan điểm.","en":"Argue, rebut and defend a position."}'::jsonb, '{"name":"Bạn Quân","role":{"vi":"Đội phản đề","en":"Opposition team"},"focus":{"vi":"lập luận chặt, phản bác nhanh","en":"tight arguments, quick rebuttals"},"questions":[{"vi":"Số liệu bạn đưa ra lấy từ nguồn nào?","en":"Where does your data come from?"},{"vi":"Nếu lập luận của bạn đúng, sao các nơi khác chưa áp dụng?","en":"If you are right, why hasn’t everyone done it already?"},{"vi":"Bạn trả lời thế nào về chi phí của giải pháp này?","en":"How do you answer the cost of your solution?"}]}'::jsonb, 'mic.jpg', 4) on conflict (goal) do update set title = excluded.title, description = excluded.description, ai_persona = excluded.ai_persona, cover_image = excluded.cover_image, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('debating', 'debating-1', '{"vi":"Có nên cấm điện thoại trong lớp học?","en":"Should phones be banned in classrooms?"}'::jsonb, 0) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('debating', 'debating-2', '{"vi":"Học đại học có còn cần thiết trong thời đại AI?","en":"Is university still necessary in the age of AI?"}'::jsonb, 1) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('debating', 'debating-3', '{"vi":"Mạng xã hội gây hại nhiều hơn lợi cho người trẻ","en":"Social media does more harm than good to young people"}'::jsonb, 2) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.practice_prompts (goal, key, text, sort_order) values ('debating', 'debating-4', '{"vi":"Nên miễn học phí cho toàn bộ sinh viên","en":"University tuition should be free for all students"}'::jsonb, 3) on conflict (key) do update set text = excluded.text, sort_order = excluded.sort_order;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'de1', 1, 'structure', '{"vi":"Luận điểm, lý do, dẫn chứng","en":"Claim, reason, evidence"}'::jsonb, '[{"vi":"Luận điểm: một câu khẳng định rõ ràng.","en":"Claim: one clear statement."},{"vi":"Lý do: vì sao điều đó đúng.","en":"Reason: why it is true."},{"vi":"Dẫn chứng: số liệu, nghiên cứu hoặc ví dụ có nguồn.","en":"Evidence: data, research or a sourced example."}]'::jsonb, '{"vi":"Mỗi luận điểm chỉ nên có một dẫn chứng mạnh nhất.","en":"Give each claim its single strongest piece of evidence."}'::jsonb, '{"vi":"Viết 2 luận điểm ủng hộ việc cấm điện thoại trong lớp học.","en":"Write 2 claims supporting a classroom phone ban."}'::jsonb, 'script', 90, 12 from public.courses where goal = 'debating' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'de2', 2, 'content', '{"vi":"Phản bác có dẫn chứng","en":"Rebuttal with evidence"}'::jsonb, '[{"vi":"Tóm tắt lại lập luận của đối phương một cách công bằng.","en":"Summarise the other side’s argument fairly."},{"vi":"Chỉ ra điểm yếu: thiếu dẫn chứng, suy diễn sai, hoặc ngoại lệ.","en":"Point out the flaw: no evidence, false logic, or exceptions."},{"vi":"Đưa dẫn chứng phản bác của bạn.","en":"Give your counter-evidence."}]'::jsonb, '{"vi":"Phản bác ý, không công kích người.","en":"Attack the idea, never the person."}'::jsonb, '{"vi":"Phản bác trong 1 phút: “Điện thoại giúp học sinh tra cứu nhanh hơn.”","en":"Rebut in 1 minute: “Phones help students look things up faster.”"}'::jsonb, 'audio', 60, 12 from public.courses where goal = 'debating' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'de3', 3, 'pace', '{"vi":"Nói chắc dưới áp lực thời gian","en":"Speaking steadily under time pressure"}'::jsonb, '[{"vi":"Biết trước bạn có bao nhiêu giây cho mỗi luận điểm.","en":"Know how many seconds you have for each point."},{"vi":"Giữ tốc độ đều, không tăng tốc khi gần hết giờ.","en":"Keep an even pace, don’t rush near the end."},{"vi":"Bỏ ý phụ trước khi bỏ phần kết.","en":"Drop minor points before you drop your conclusion."}]'::jsonb, '{"vi":"Tập với đồng hồ đếm ngược.","en":"Practise with a countdown timer."}'::jsonb, '{"vi":"Trình bày lập trường của bạn trong đúng 60 giây.","en":"Present your position in exactly 60 seconds."}'::jsonb, 'audio', 60, 10 from public.courses where goal = 'debating' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
insert into public.lessons (course_id, slug, position, skill, title, theory, tip, task, suggested_kind, target_sec, est_minutes) select id, 'de4', 4, 'closing', '{"vi":"Tổng kết lập trường","en":"Summing up your case"}'::jsonb, '[{"vi":"Nhắc lại 2 luận điểm mạnh nhất.","en":"Repeat your 2 strongest claims."},{"vi":"Chỉ ra vì sao lập luận đối phương yếu hơn.","en":"Show why the other side is weaker."},{"vi":"Kết bằng một câu dễ nhớ.","en":"End with one memorable line."}]'::jsonb, '{"vi":"Câu kết nên ngắn hơn 15 từ.","en":"Keep your final line under 15 words."}'::jsonb, '{"vi":"Ghi âm phần tổng kết 45 giây cho đội của bạn.","en":"Record a 45-second summary for your team."}'::jsonb, 'audio', 45, 10 from public.courses where goal = 'debating' on conflict (slug) do update set position = excluded.position, skill = excluded.skill, title = excluded.title, theory = excluded.theory, tip = excluded.tip, task = excluded.task, suggested_kind = excluded.suggested_kind, target_sec = excluded.target_sec, est_minutes = excluded.est_minutes;
